//! Minimal IDNA/punycode-style helper library.
//!
//! Re-implemented from scratch (std only) to match the observable behavior
//! of the original C++ `idna.hpp` used by `test11.cpp`.

pub mod convert;
pub mod punycode;
pub mod validate;

pub use convert::{normalize, to_ascii, to_lower, to_unicode};
pub use punycode::{punycode_decode, punycode_encode};
pub use validate::{count_labels, is_ascii_domain, is_idn_domain, is_valid_domain, is_valid_label};

/// ACE (ASCII Compatible Encoding) prefix used by all conversions.
pub(crate) const ACE_PREFIX: &str = "xn--";

//! Domain name conversion helpers.

use super::ACE_PREFIX;

/// ASCII-only lowercasing: bytes `A-Z` become `a-z`, everything else
/// (including non-ASCII UTF-8 bytes) is left untouched.
pub fn to_lower(input: &str) -> String {
    input
        .bytes()
        .map(|b| if b.is_ascii_uppercase() { b + 32 } else { b })
        .map(|b| b as char)
        .collect()
}

/// Normalization applied by this library: ASCII lowercasing.
pub fn normalize(input: &str) -> String {
    to_lower(input)
}

/// Convert a (possibly Unicode) domain to its ASCII form:
/// the lowercased input prefixed with the ACE prefix.
pub fn to_ascii(input: &str) -> String {
    let mut out = String::with_capacity(ACE_PREFIX.len() + input.len());
    out.push_str(ACE_PREFIX);
    out.push_str(&to_lower(input));
    out
}

/// Convert an ASCII (ACE) domain back to Unicode: strip one leading
/// ACE prefix if present, otherwise return the input unchanged.
pub fn to_unicode(input: &str) -> String {
    input
        .strip_prefix(ACE_PREFIX)
        .unwrap_or(input)
        .to_string()
}

//! Punycode-style encode/decode helpers.

use super::ACE_PREFIX;

/// "Encode" a label: prepend the ACE prefix, leaving the body untouched.
pub fn punycode_encode(input: &str) -> String {
    let mut out = String::with_capacity(ACE_PREFIX.len() + input.len());
    out.push_str(ACE_PREFIX);
    out.push_str(input);
    out
}

/// "Decode" a label: strip one leading ACE prefix if present,
/// otherwise return the input unchanged.
pub fn punycode_decode(input: &str) -> String {
    input
        .strip_prefix(ACE_PREFIX)
        .unwrap_or(input)
        .to_string()
}

//! Domain/label validation and inspection helpers.

/// A domain is valid when it is non-empty and at most 255 bytes long.
pub fn is_valid_domain(input: &str) -> bool {
    !input.is_empty() && input.len() <= 255
}

/// A label is valid when it is non-empty and at most 63 bytes long.
pub fn is_valid_label(input: &str) -> bool {
    !input.is_empty() && input.len() <= 63
}

/// True when every byte of the input is ASCII (`< 0x80`).
pub fn is_ascii_domain(input: &str) -> bool {
    input.bytes().all(|b| b.is_ascii())
}

/// True when the input contains at least one non-ASCII byte.
pub fn is_idn_domain(input: &str) -> bool {
    input.bytes().any(|b| !b.is_ascii())
}

/// Number of labels in a domain: one plus the number of `.` separators.
pub fn count_labels(input: &str) -> usize {
    1 + input.bytes().filter(|&b| b == b'.').count()
}

//! Entry point mirroring `test11.cpp`: calls 11 different idna APIs
//! for each input and prints the results, one line per input.

mod idna;

use std::env;

fn main() {
    let args: Vec<String> = env::args().skip(1).collect();

    let inputs: Vec<String> = if !args.is_empty() {
        args
    } else {
        vec![
            "one".to_string(),
            "two.three".to_string(),
            "four.five.six".to_string(),
        ]
    };

    for input in &inputs {
        println!(
            "{} {} {} {} {} {} {} {} {} {} {}",
            idna::to_ascii(input),
            idna::to_unicode(input),
            idna::punycode_encode(input),
            idna::punycode_decode(input),
            idna::is_valid_domain(input) as i32,
            idna::is_valid_label(input) as i32,
            idna::is_ascii_domain(input) as i32,
            idna::is_idn_domain(input) as i32,
            idna::to_lower(input),
            idna::normalize(input),
            idna::count_labels(input),
        );
    }
}

